<div class="page-header"><div><span class="page-eyebrow">Partner membership operations</span><h2>Subscription Requests</h2><p>Review pause, resume and cancellation requests before any membership status changes.</p></div><a class="btn" href="<?= htmlspecialchars(url('/admin/subscription-plans')) ?>"><i data-lucide="layers-3"></i> Subscription plans</a></div>
<div class="request-filter-tabs"><?php foreach(['pending'=>'Awaiting review','approved'=>'Approved','rejected'=>'Rejected','all'=>'All requests'] as $key=>$label): ?><a class="<?= $status===$key?'active':'' ?>" href="<?= htmlspecialchars(url('/admin/subscription-requests?status='.$key)) ?>"><?= htmlspecialchars($label) ?></a><?php endforeach; ?></div>
<section class="subscription-request-list"><?php if(!$requests): ?><div class="workspace-empty"><i data-lucide="inbox"></i>No <?= htmlspecialchars($status==='all'?'':' '.$status) ?> subscription requests.</div><?php else: foreach($requests as $request): $name=trim((string)($request['company_name']?:$request['first_name'].' '.$request['last_name'])); ?><article><div class="request-avatar"><?= htmlspecialchars(strtoupper(mb_substr($name ?: 'P',0,1))) ?></div><div class="request-copy"><span class="status-pill <?= htmlspecialchars((string)$request['status']) ?>"><?= htmlspecialchars(ucfirst((string)$request['status'])) ?></span><h3><?= htmlspecialchars($name ?: (string)$request['email']) ?> <small>requested <?= htmlspecialchars((string)$request['request_type']) ?></small></h3><p><strong><?= htmlspecialchars((string)$request['plan_name']) ?></strong> · <?= htmlspecialchars((string)($request['reason']?:'No reason provided')) ?></p><small><?= htmlspecialchars(date('d M Y, h:i A',strtotime((string)$request['created_at']))) ?></small></div><?php if($request['status']==='pending'): ?><form method="post" action="<?= htmlspecialchars(url('/admin/subscription-requests/'.$request['id'].'/review')) ?>" class="request-review-form"><?=csrf_field()?><input name="admin_note" placeholder="Optional note for partner"><div><button class="btn btn-sm" name="decision" value="reject" type="submit">Reject</button><button class="btn btn-sm btn-primary" name="decision" value="approve" type="submit">Approve</button></div></form><?php else: ?><div class="request-reviewed"><strong><?= htmlspecialchars(ucfirst((string)$request['status'])) ?></strong><small><?= htmlspecialchars((string)($request['admin_note']?:'No admin note')) ?></small></div><?php endif; ?></article><?php endforeach; endif; ?></section>
